def seed_coverage_zones_and_permissions(apps, schema_editor):
    database = schema_editor.connection.alias
    CoverageZone = apps.get_model('core', 'CoverageZone')
    Permission = apps.get_model('core', 'Permission')
    Role = apps.get_model('core', 'Role')
    RolePermission = apps.get_model('core', 'RolePermission')

    for name in INITIAL_ZONES:
        normalized_name = ' '.join(name.split()).casefold()
        CoverageZone.objects.using(database).get_or_create(
            normalized_name=normalized_name,
            defaults={'name': ' '.join(name.split())},
        )

    permissions = {}
    for action, label in (('view', 'Consultar'), ('manage', 'Administrar')):
        permissions[action], _ = Permission.objects.using(database).get_or_create(
            module='coverage',
            action=action,
            defaults={'name': f'Gestión de cobertura: {label}'},
        )

    role_permissions = {
        'gerente': ('view', 'manage'),
        'jefe-comercial': ('view', 'manage'),
        'jefe-tecnico': ('view', 'manage'),
        'caja': ('view',),
        'call-center': ('view',),
    }
    technical_lead, _ = Role.objects.using(database).get_or_create(
        code='jefe-tecnico',
        defaults={
            'name': 'Jefe Técnico',
            'description': 'Administra zonas de cobertura',
            'active': True,
            'is_system_role': False,
        },
    )
    roles = {
        role.code: role
        for role in Role.objects.using(database).filter(
            code__in=role_permissions)
    }
    roles['jefe-tecnico'] = technical_lead
    for role_code, actions in role_permissions.items():
        role = roles.get(role_code)
        if role is None:
            continue
        for action in actions:
            RolePermission.objects.using(database).get_or_create(
                role=role,
                permission=permissions[action],
            )


